questionvariables.text:
/*STA 141 week2 quizes*/
correct_answer:rand_selection([
[1, true, "Snowballing"],
[2, true, "Convenience sampling"],
[3, true, "Judgemental sampling"]
], 1);
incorrect_answers:rand_selection([
[4, false, "Simple random sampling"],
[5, false, "Multistage sampling"],
[6, false, "Systematic sampling"]
], 2);
ta: random_permutation(append(correct_answer,incorrect_answers));

ta_index: sort(makelist(x[1], x, ta));
ta_largest: last(ta_index);
